    function init3() external onlyOwner reinitializer(3) {
        LibForcedInclusion.Storage storage $ = _forcedInclusionStorage;
        (uint48 head, uint48 tail) = ($.head, $.tail);
        $.head = tail;
        emit ForcedInclusionsVoided(head, tail);
